import { writeFileSync } from "node:fs";
import { allServices } from "../src/lib/content/services";

// The CMS is a separate deployable. Keep its CommonJS array API and regenerate
// its data rather than importing the Next.js application at runtime.
writeFileSync(
  new URL("../server/utils/services.js", import.meta.url),
  "// Generated by scripts/generateServiceCatalogue.ts. Do not edit by hand.\nmodule.exports = " +
    JSON.stringify(allServices, null, 2) + ";\n",
);
